package com.osrsbingo;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import javax.inject.Inject;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * OSRS Bingo RuneLite plugin.
 *
 * Listens for in-game events and forwards them to the OSRS Bingo backend
 * via the webhook API so tiles can be automatically verified.
 *
 * Events captured:
 *   - {@link NpcLootReceived}  → MonsterDrop tiles
 *   - {@link StatChanged}      → XpGoal tiles (fires on every XP gain)
 *   - {@link ChatMessage}      → BossKc tiles (kill count chat messages)
 *   - Heartbeat timer          → periodic ping every 5 minutes
 *
 * The plugin requires an API key configured in the plugin settings panel.
 * The key is generated in the OSRS Bingo web app profile page.
 */
@Slf4j
@PluginDescriptor(
    name = "OSRS Bingo",
    description = "Automatically validates bingo tiles by sending game events to the OSRS Bingo server.",
    tags = {"bingo", "osrs", "competition", "clan"}
)
public class OsrsBingoPlugin extends Plugin
{
    // Matches kill count chat messages like:
    //   "Your Zulrah kill count is: 50."
    //   "Your General Graardor kill count is: 100."
    private static final Pattern KC_PATTERN =
        Pattern.compile("Your (.+) kill count is: (\\d+)\\.");

    @Inject
    private Client client;

    @Inject
    private OsrsBingoConfig config;

    @Inject
    private BingoApiClient apiClient;

    // Separate thread for the heartbeat timer (not the game thread)
    private ScheduledExecutorService heartbeatExecutor;

    // Track previous XP to compute delta (StatChanged gives new total, not delta)
    private final int[] previousXp = new int[Skill.values().length];
    private boolean xpInitialised = false;

    @Override
    protected void startUp()
    {
        log.info("OSRS Bingo plugin started.");
        xpInitialised = false;

        heartbeatExecutor = Executors.newSingleThreadScheduledExecutor();
        heartbeatExecutor.scheduleAtFixedRate(this::sendHeartbeat, 1, 5, TimeUnit.MINUTES);
    }

    @Override
    protected void shutDown()
    {
        log.info("OSRS Bingo plugin stopped.");
        if (heartbeatExecutor != null)
        {
            heartbeatExecutor.shutdownNow();
        }
    }

    // ── Event handlers ─────────────────────────────────────────────────

    /**
     * Fires when the local player receives loot from an NPC.
     * Sends a drop event for each item in the loot stack.
     */
    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event)
    {
        if (!config.sendDrops()) return;

        NPC npc = event.getNpc();
        for (ItemStack item : event.getItems())
        {
            String itemName = resolveItemName(item.getId());
            log.debug("OSRS Bingo: Drop — {} x{} from {}", itemName, item.getQuantity(), npc.getName());

            apiClient.sendDrop(new BingoApiClient.DropEvent(
                npc.getId(),
                npc.getName() != null ? npc.getName() : "Unknown",
                item.getId(),
                itemName,
                item.getQuantity()
            ));
        }
    }

    /**
     * Fires when any skill's XP changes. Calculates the XP gained since the last
     * event and sends it to the backend.
     *
     * Note: On login, all skills fire with the current total XP. We capture the
     * baseline on the first tick and only send deltas from the second event onward.
     */
    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        if (!config.sendXp()) return;

        int skillIndex = event.getSkill().ordinal();
        int newXp = event.getXp();

        if (!xpInitialised)
        {
            // Capture baseline on first stat change (login tick)
            previousXp[skillIndex] = newXp;
            return;
        }

        int gained = newXp - previousXp[skillIndex];
        previousXp[skillIndex] = newXp;

        if (gained <= 0) return;

        String skillName = event.getSkill().getName().toLowerCase();
        log.debug("OSRS Bingo: XP — {} gained {} (total {})", skillName, gained, newXp);

        apiClient.sendXp(new BingoApiClient.XpEvent(skillName, newXp, gained));
    }

    /**
     * Fires on every chat message. Parses kill count messages to extract the boss
     * name and new KC, then sends a KC event.
     */
    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (!config.sendKc()) return;
        if (event.getType() != ChatMessageType.GAMEMESSAGE) return;

        String message = event.getMessage().replaceAll("<[^>]*>", ""); // strip colour tags
        Matcher matcher = KC_PATTERN.matcher(message);
        if (!matcher.matches()) return;

        String bossName = matcher.group(1);
        int killCount = Integer.parseInt(matcher.group(2));

        log.debug("OSRS Bingo: KC — {} × {}", bossName, killCount);
        apiClient.sendKc(new BingoApiClient.KcEvent(bossName, killCount));
    }

    /**
     * Fires once per game tick. Used to initialise the XP baseline after login
     * (the first few StatChanged events are the initial XP load, not actual gains).
     */
    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!xpInitialised && client.getGameState() == GameState.LOGGED_IN)
        {
            // Populate baseline XP from the current skill levels
            for (Skill skill : Skill.values())
            {
                if (skill.ordinal() < previousXp.length)
                {
                    previousXp[skill.ordinal()] = client.getSkillExperience(skill);
                }
            }
            xpInitialised = true;
            log.debug("OSRS Bingo: XP baseline initialised.");
        }
    }

    /**
     * Fires when the player's login state changes. On the LOGGED_IN transition
     * we immediately send a heartbeat so the backend can bind the RSN without
     * waiting up to a minute for the periodic scheduler to tick.
     *
     * <p>
     * This is the "first-time verification" fast path: a user who has just
     * pasted their API key sees the profile page flip to Verified within a
     * second or two of logging into OSRS instead of having to wait out the
     * scheduler's initial delay.
     * </p>
     */
    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            // Deferred by 2 seconds so client.getLocalPlayer() is populated —
            // immediately on LOGGED_IN the player name can still be null.
            if (heartbeatExecutor != null && !heartbeatExecutor.isShutdown())
            {
                heartbeatExecutor.schedule(this::sendHeartbeat, 2, TimeUnit.SECONDS);
            }
        }
    }

    // ── Helpers ────────────────────────────────────────────────────────

    private void sendHeartbeat()
    {
        if (client.getGameState() != GameState.LOGGED_IN) return;

        String rsn = client.getLocalPlayer() != null
            ? client.getLocalPlayer().getName()
            : "";

        apiClient.sendHeartbeat(new BingoApiClient.HeartbeatEvent(rsn, client.getWorld()));
    }

    private String resolveItemName(int itemId)
    {
        // ItemManager is not available via simple injection in external plugins;
        // use the item composition if available, otherwise fall back to the ID string.
        try
        {
            ItemComposition comp = client.getItemDefinition(itemId);
            return comp != null ? comp.getName() : "Item #" + itemId;
        }
        catch (Exception e)
        {
            return "Item #" + itemId;
        }
    }

    @Provides
    OsrsBingoConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(OsrsBingoConfig.class);
    }
}

package com.osrsbingo;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;

/**
 * Async HTTP client for the OSRS Bingo backend webhook endpoints.
 *
 * All methods are fire-and-forget (async, no response handling beyond logging).
 * The plugin should not block the game thread waiting for HTTP responses.
 *
 * Authentication: every request includes the X-Runelite-Key header populated
 * from the user's configured API key.
 *
 * Endpoints called:
 *   POST /api/webhook/runelite/drop      — monster drop events
 *   POST /api/webhook/runelite/xp        — XP gain events
 *   POST /api/webhook/runelite/kc        — boss kill count events
 *   POST /api/webhook/runelite/heartbeat — periodic ping
 */
@Slf4j
@Singleton
public class BingoApiClient
{
    private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

    private final OkHttpClient http;
    private final Gson gson;
    private final OsrsBingoConfig config;

    @Inject
    public BingoApiClient(OkHttpClient http, Gson gson, OsrsBingoConfig config)
    {
        this.http = http;
        this.gson = gson;
        this.config = config;
    }

    /**
     * Sends a drop event to the backend asynchronously.
     * No-ops if the API key is not configured.
     *
     * @param payload The drop event data (NPC, item, quantity).
     */
    public void sendDrop(DropEvent payload)
    {
        post("/api/webhook/runelite/drop", payload);
    }

    /**
     * Sends an XP gain event to the backend asynchronously.
     *
     * @param payload The XP event data (skill, total XP, XP gained).
     */
    public void sendXp(XpEvent payload)
    {
        post("/api/webhook/runelite/xp", payload);
    }

    /**
     * Sends a boss kill count event to the backend asynchronously.
     *
     * @param payload The KC event data (boss name, new kill count).
     */
    public void sendKc(KcEvent payload)
    {
        post("/api/webhook/runelite/kc", payload);
    }

    /**
     * Sends a heartbeat to the backend. Called every few minutes.
     *
     * @param payload The heartbeat data (RSN, world).
     */
    public void sendHeartbeat(HeartbeatEvent payload)
    {
        post("/api/webhook/runelite/heartbeat", payload);
    }

    // ── Private helpers ────────────────────────────────────────────────

    private void post(String path, Object body)
    {
        String key = config.apiKey();
        if (key == null || key.isBlank())
        {
            log.debug("OSRS Bingo: API key not configured, skipping {}", path);
            return;
        }

        String baseUrl = config.backendUrl();
        if (baseUrl == null || baseUrl.isBlank())
        {
            log.warn("OSRS Bingo: Backend URL not configured.");
            return;
        }

        String json = gson.toJson(body);
        Request request = new Request.Builder()
            .url(baseUrl + path)
            .header("X-Runelite-Key", key)
            .header("Content-Type", "application/json")
            .post(RequestBody.create(JSON, json))
            .build();

        http.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                log.warn("OSRS Bingo: Failed to send event to {}: {}", path, e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                try (response)
                {
                    if (!response.isSuccessful())
                    {
                        log.warn("OSRS Bingo: Backend returned {} for {}", response.code(), path);
                    }
                }
            }
        });
    }

    // ── Event payload classes ──────────────────────────────────────────

    public static class DropEvent
    {
        public int npcId;
        public String npcName;
        public int itemId;
        public String itemName;
        public int quantity;

        public DropEvent(int npcId, String npcName, int itemId, String itemName, int quantity)
        {
            this.npcId = npcId;
            this.npcName = npcName;
            this.itemId = itemId;
            this.itemName = itemName;
            this.quantity = quantity;
        }
    }

    public static class XpEvent
    {
        public String skill;
        public long totalXp;
        public long xpGained;

        public XpEvent(String skill, long totalXp, long xpGained)
        {
            this.skill = skill;
            this.totalXp = totalXp;
            this.xpGained = xpGained;
        }
    }

    public static class KcEvent
    {
        public String bossName;
        public int killCount;

        public KcEvent(String bossName, int killCount)
        {
            this.bossName = bossName;
            this.killCount = killCount;
        }
    }

    public static class HeartbeatEvent
    {
        public String rsn;
        public int world;

        public HeartbeatEvent(String rsn, int world)
        {
            this.rsn = rsn;
            this.world = world;
        }
    }
}

package com.osrsbingo;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

/**
 * RuneLite config panel for the OSRS Bingo plugin.
 *
 * Users configure two things here:
 *   1. Backend URL — the address of their bingo server (default: localhost for development).
 *   2. API Key     — the 64-character key generated in the web app profile page.
 *                    This is sent in the X-Runelite-Key header on every webhook call.
 */
@ConfigGroup(OsrsBingoConfig.GROUP)
public interface OsrsBingoConfig extends Config
{
    String GROUP = "osrsbingo";

    @ConfigSection(
        name = "Connection",
        description = "Backend server connection settings",
        position = 0
    )
    String connectionSection = "connection";

    @ConfigItem(
        keyName = "backendUrl",
        name = "Backend URL",
        description = "The base URL of the OSRS Bingo backend server (no trailing slash).",
        section = connectionSection,
        position = 0
    )
    default String backendUrl()
    {
        return "https://tilelite.app";
    }

    @ConfigItem(
        keyName = "apiKey",
        name = "API Key",
        description = "Your RuneLite API key from the OSRS Bingo profile page. Required for event validation.",
        secret = true,
        section = connectionSection,
        position = 1
    )
    default String apiKey()
    {
        return "";
    }

    @ConfigSection(
        name = "Events",
        description = "Which game events to send to the server",
        position = 1
    )
    String eventsSection = "events";

    @ConfigItem(
        keyName = "sendDrops",
        name = "Send drop events",
        description = "Send monster drop events (required for MonsterDrop tile validation).",
        section = eventsSection,
        position = 0
    )
    default boolean sendDrops()
    {
        return true;
    }

    @ConfigItem(
        keyName = "sendXp",
        name = "Send XP events",
        description = "Send XP gain events (required for XpGoal tile validation).",
        section = eventsSection,
        position = 1
    )
    default boolean sendXp()
    {
        return true;
    }

    @ConfigItem(
        keyName = "sendKc",
        name = "Send kill count events",
        description = "Send boss kill count events (required for BossKc tile validation).",
        section = eventsSection,
        position = 2
    )
    default boolean sendKc()
    {
        return true;
    }
}
